do $$
declare r record; n int;
begin
  delete from _dz d where exists (select 1 from mp_pcells pc where pc.x between d.x * 5 and d.x * 5 + 4 and pc.y between d.y * 5 and d.y * 5 + 4);
  insert into mp_zone(x, y, z) select x, y, z from _dz on conflict (x, y) do update set z = excluded.z;
  get diagnostics n = row_count;
  for r in select d, min(x) x0, min(y) y0, max(x) x1, max(y) y1 from _dz group by d loop
    perform _mp_chg('zone', null, 'set', box(point(r.x0, r.y0), point(r.x1 + 1, r.y1 + 1)));
  end loop;
  raise warning '用途地域をぬりかえたマス：%', n;
end $$;
